test.describe("TC-002: Cart badge reflects added and removed items", () => {
  test("should update the cart badge as items are added and removed", async ({ page }) => {
    await loginAs(page, "standard_user");

    const badge = page.locator('[data-test="shopping-cart-badge"]');
    const backpackButton = page.locator('[data-test="add-to-cart-sauce-labs-backpack"]');
    const backpackRemove = page.locator('[data-test="remove-sauce-labs-backpack"]');

    await backpackButton.click();
    await expect(badge).toHaveText("1");

    await page.locator('[data-test="add-to-cart-sauce-labs-bike-light"]').click();
    await expect(badge).toHaveText("2");

    await backpackRemove.click();
    await expect(badge).toHaveText("1");
    await expect(backpackButton).toHaveText("Add to cart");

    await page.locator('[data-test="shopping-cart-link"]').click();
    await expect(page).toHaveURL(/cart/);
    const items = page.locator('[data-test="inventory-item"]');
    await expect(items).toHaveCount(1);
    await expect(items.locator('[data-test="inventory-item-name"]')).toHaveText("Sauce Labs Bike Light");
  });
});

